import {createFilter, listFilters, getFilter, updateFilter, deleteFilter} from './filters.js';
import {searchIssues} from './search.js';

export function registerFilterRoutes(ctx) {
  const {app, requireAuth} = ctx;
  app.get('/api/v1/filters', requireAuth, (req, res) => res.json(listFilters(ctx, req)));
  app.post('/api/v1/filters', requireAuth, (req, res) => res.status(201).json({filter: createFilter(ctx, req, req.body)}));
  app.get('/api/v1/filters/:filterId', requireAuth, (req, res) => res.json({filter: getFilter(ctx, req, req.params.filterId)}));
  app.patch('/api/v1/filters/:filterId', requireAuth, (req, res) => res.json({filter: updateFilter(ctx, req, req.params.filterId, req.body)}));
  app.delete('/api/v1/filters/:filterId', requireAuth, (req, res) => {
    deleteFilter(ctx, req, req.params.filterId);
    res.json({ok: true});
  });
  app.get('/api/v1/filters/:filterId/search', requireAuth, (req, res) => {
    const filter = getFilter(ctx, req, req.params.filterId);
    res.json({...searchIssues(ctx, req, {...req.query, orgId: filter.orgId, q: filter.query}), filter});
  });
}

import {AppError, savedFilterInput, validatedQuery, integer} from '@crew/shared';
import {searchAccess, validateQueryProjects} from './search.js';

export function publicFilter(row, userId) {
  return {id: row.id, orgId: row.org_id, ownerId: row.owner_id, teamId: row.team_id,
    visibility: row.visibility, name: row.name, description: row.description, query: row.query,
    revision: row.revision, createdAt: row.created_at, updatedAt: row.updated_at, canEdit: row.owner_id === userId};
}

function teamMember(ctx, userId, teamId, orgId) {
  return Boolean(ctx.db.prepare(`SELECT 1 FROM teams t JOIN team_members tm ON tm.team_id=t.id
    WHERE t.id=? AND t.org_id=? AND tm.user_id=?`).get(teamId, orgId, userId));
}

function queryVisible(ctx, row, projectIds) {
  try {
    validateQueryProjects(ctx, validatedQuery(row.query).ast, row.org_id, projectIds);
    return true;
  } catch (error) {
    if (error.code === 'FORBIDDEN') return false;
    throw error;
  }
}

export function canReadFilter(ctx, req, row) {
  if (!ctx.permissions.membership(req.user.id, row.org_id)) return false;
  if (row.visibility === 'personal' && row.owner_id !== req.user.id) return false;
  if (row.visibility === 'team' && !teamMember(ctx, req.user.id, row.team_id, row.org_id)) return false;
  const projectIds = ctx.permissions.projectIds(req.user.id, row.org_id).filter(id => ctx.permissions.canProject(req.user.id, id, 'insight:read'));
  return queryVisible(ctx, row, projectIds);
}

export function getFilter(ctx, req, id, {edit = false} = {}) {
  ctx.permissions.scope(req, edit ? 'insight:write' : 'insight:read');
  const row = ctx.db.prepare('SELECT * FROM saved_filters WHERE id=?').get(id);
  if (!row || !canReadFilter(ctx, req, row)) throw new AppError('NOT_FOUND', 'Saved filter not found', 404);
  if (edit) {
    if (row.owner_id !== req.user.id) throw new AppError('FORBIDDEN', 'Only the filter creator can change it', 403);
    ctx.permissions.assertOrg(req, row.org_id, 'insight:write');
  }
  return publicFilter(row, req.user.id);
}

export function listFilters(ctx, req) {
  const access = searchAccess(ctx, req);
  if (req.query.visibility && !['personal', 'team', 'all'].includes(req.query.visibility)) throw new AppError('VALIDATION', 'Unknown filter visibility', 422, {visibility: 'Choose personal, team or all'});
  const rows = ctx.db.prepare('SELECT * FROM saved_filters WHERE org_id=? ORDER BY updated_at DESC,id').all(access.orgId);
  const items = rows.filter(row => canReadFilter(ctx, req, row))
    .filter(row => !req.query.visibility || req.query.visibility === 'all' || row.visibility === req.query.visibility)
    .filter(row => !req.query.teamId || row.team_id === req.query.teamId)
    .filter(row => req.query.owned !== 'true' || row.owner_id === req.user.id)
    .map(row => publicFilter(row, req.user.id));
  return {...ctx.paginate(items, req.query), total: items.length};
}

function checkFilter(ctx, req, input) {
  ctx.permissions.assertOrg(req, input.orgId, 'insight:write');
  const projects = ctx.permissions.projectIds(req.user.id, input.orgId);
  validateQueryProjects(ctx, validatedQuery(input.query).ast, input.orgId, projects);
  if (input.visibility === 'team') {
    if (!input.teamId || !teamMember(ctx, req.user.id, input.teamId, input.orgId)) throw new AppError('VALIDATION', 'Choose one of your teams in this organization', 422, {teamId: 'Team membership is required to share a filter'});
  } else if (input.teamId) throw new AppError('VALIDATION', 'A personal filter cannot have a team', 422, {teamId: 'Clear the team or choose team visibility'});
}

function uniqueName(ctx, userId, input, exceptId = '') {
  const duplicate = ctx.db.prepare(`SELECT id FROM saved_filters WHERE owner_id=? AND org_id=?
    AND name=? COLLATE NOCASE AND visibility=? AND COALESCE(team_id,'')=COALESCE(?,'') AND id<>?`)
    .get(userId, input.orgId, input.name, input.visibility, input.teamId, exceptId);
  if (duplicate) throw new AppError('CONFLICT', 'You already saved a filter with this name in this destination', 409, {name: 'Choose a distinct name'});
}

function emitFilter(ctx, req, action, before, after) {
  const filter = after ?? before;
  ctx.bus.emit({actorId: req.user.id, orgId: filter.orgId, entityType: 'savedFilter', entityId: filter.id,
    action, before, after, time: ctx.now()});
}

export function createFilter(ctx, req, body) {
  const input = savedFilterInput(body);
  checkFilter(ctx, req, input);
  const id = ctx.id(), now = ctx.now();
  ctx.transaction(() => {
    uniqueName(ctx, req.user.id, input);
    ctx.db.prepare(`INSERT INTO saved_filters(id,org_id,owner_id,team_id,visibility,name,description,query,created_at,updated_at)
      VALUES(?,?,?,?,?,?,?,?,?,?)`).run(id, input.orgId, req.user.id, input.teamId, input.visibility, input.name, input.description, input.query, now, now);
  });
  const filter = getFilter(ctx, req, id);
  emitFilter(ctx, req, 'created', null, filter);
  return filter;
}

export function updateFilter(ctx, req, id, body) {
  const before = getFilter(ctx, req, id, {edit: true});
  const {expectedRevision, ...changes} = body ?? {};
  const input = {...before, ...savedFilterInput(changes, {partial: true})};
  if (input.orgId !== before.orgId) throw new AppError('VALIDATION', 'A saved filter cannot move organizations', 422, {orgId: 'Create a new filter in the other organization'});
  if (expectedRevision !== undefined && integer(expectedRevision, 'expectedRevision', {min: 1}) !== before.revision) throw new AppError('CONFLICT', 'This filter changed; reload before saving', 409, {expectedRevision: 'The saved revision is newer'});
  checkFilter(ctx, req, input);
  ctx.transaction(() => {
    uniqueName(ctx, req.user.id, input, id);
    ctx.db.prepare('UPDATE saved_filters SET name=?,description=?,query=?,visibility=?,team_id=?,revision=revision+1,updated_at=? WHERE id=?')
      .run(input.name, input.description, input.query, input.visibility, input.teamId, ctx.now(), id);
  });
  const filter = getFilter(ctx, req, id);
  emitFilter(ctx, req, 'updated', before, filter);
  return filter;
}

export function deleteFilter(ctx, req, id) {
  const before = getFilter(ctx, req, id, {edit: true});
  ctx.db.prepare('DELETE FROM saved_filters WHERE id=?').run(id);
  emitFilter(ctx, req, 'deleted', before, null);
}
